import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { randomBytes } from 'node:crypto';
import { Readable, Writable } from 'node:stream';
import { captureEncryptedArchive, authenticateEncryptedArchive, restoreAuthenticatedArchive } from './private-recovery-archive.mjs';

async function fixture() {
  // Synthetic generated bytes only; no user/production input or credentials.
  const directory = await fs.mkdtemp(path.join(os.tmpdir(), 'socius-archive-synthetic-'));
  const file = path.join(directory, 'synthetic.aes'), key = randomBytes(32), bytes = randomBytes(256 * 1024);
  const manifest = await captureEncryptedArchive({ source: Readable.from([bytes.subarray(0, 50000), bytes.subarray(50000)]),
    destination: file, key, waitForSuccess: async () => {} });
  return { path: file, key, bytes, manifest };
}
function staging(chunks) { return new Writable({ write(chunk, encoding, callback) { chunks.push(Buffer.from(chunk)); callback(); } }); }

test('authenticated synthetic streaming roundtrip and exact manifest sizes', async () => {
  const f = await fixture(), chunks = [];
  assert.equal(f.manifest.bytes, f.bytes.length);
  assert.equal(f.manifest.ciphertextBytes, f.bytes.length);
  assert.notEqual(f.manifest.plaintextSha256, f.manifest.ciphertextSha256);
  assert.equal((await authenticateEncryptedArchive(f)).authenticated, true);
  assert.equal((await restoreAuthenticatedArchive({ ...f, createDestination: () => staging(chunks) })).staged, true);
  assert.deepEqual(Buffer.concat(chunks), f.bytes);
});

for (const corruption of ['ciphertext', 'tag', 'key', 'truncated', 'appended', 'digest']) {
  test(`refuses ${corruption} before creating any plaintext destination`, async () => {
    const f = await fixture();
    if (corruption === 'ciphertext') { const data = await fs.readFile(f.path); data[10] ^= 1; await fs.writeFile(f.path, data); }
    if (corruption === 'tag') f.manifest.tag = '00'.repeat(16);
    if (corruption === 'key') f.key = randomBytes(32);
    if (corruption === 'truncated') await fs.truncate(f.path, f.bytes.length - 1);
    if (corruption === 'appended') await fs.appendFile(f.path, Buffer.from([1]));
    if (corruption === 'digest') f.manifest.plaintextSha256 = '00'.repeat(32);
    let created = false;
    await assert.rejects(restoreAuthenticatedArchive({ ...f, createDestination() { created = true; return staging([]); } }), /do not use destination bytes/);
    assert.equal(created, false);
    await assert.rejects(authenticateEncryptedArchive(f), /no plaintext released/);
  });
}

test('does not report a successful archive when producer exits unsuccessfully', async () => {
  const f = await fixture();
  await assert.rejects(captureEncryptedArchive({ source: Readable.from([f.bytes]), destination: `${f.path}.failed`, key: f.key,
    waitForSuccess: async () => { throw new Error('SYNTHETIC_PRIVATE_DIAGNOSTIC'); } }), error => {
    assert.equal(error.message.includes('SYNTHETIC_PRIVATE_DIAGNOSTIC'), false);
    return /no completed archive metadata/.test(error.message);
  });
});

test('never overwrites an existing encrypted archive', async () => {
  const f = await fixture(), before = await fs.readFile(f.path);
  await assert.rejects(captureEncryptedArchive({ source: Readable.from([Buffer.from('other synthetic')]), destination: f.path, key: f.key, waitForSuccess: async () => {} }));
  assert.deepEqual(await fs.readFile(f.path), before);
});

test('producer failure after stdout completion still returns no completed manifest', async () => {
  const f = await fixture();
  await assert.rejects(captureEncryptedArchive({ source: Readable.from([f.bytes]), destination: `${f.path}.late-failure`, key: f.key,
    waitForSuccess: async () => { await new Promise(resolve => setTimeout(resolve, 15)); throw new Error('SYNTHETIC_LATE_EXIT'); },
  }), /no completed archive metadata/);
});

test('enforces byte bound during capture and before opening staging', async () => {
  const f = await fixture();
  await assert.rejects(captureEncryptedArchive({ source: Readable.from([f.bytes]), destination: `${f.path}.large`, key: f.key, maxBytes: 10, waitForSuccess: async () => {} }));
  let created = false;
  await assert.rejects(restoreAuthenticatedArchive({ ...f, maxBytes: 10, createDestination() { created = true; return staging([]); } }));
  assert.equal(created, false);
});

test('second-pass mutation prevents successful staging and hides diagnostics', async () => {
  const f = await fixture();
  await assert.rejects(restoreAuthenticatedArchive({ ...f, async createDestination() {
    const data = await fs.readFile(f.path); data[10] ^= 1; await fs.writeFile(f.path, data);
    return staging([]);
  } }), /do not use destination bytes/);
});

test('sink failure is generic and cannot become restore completion', async () => {
  const f = await fixture();
  await assert.rejects(restoreAuthenticatedArchive({ ...f, createDestination() {
    return new Writable({ write(chunk, encoding, callback) { callback(new Error('SYNTHETIC_SECRET_ROW')); } });
  } }), error => error.message === 'Archive private staging failed; do not use destination bytes');
});

test('missing producer success contract and malformed manifest fail closed', async () => {
  const f = await fixture();
  await assert.rejects(captureEncryptedArchive({ source: Readable.from([]), destination: `${f.path}.invalid`, key: f.key }), /completion check required/);
  await assert.rejects(authenticateEncryptedArchive({ ...f, manifest: { ...f.manifest, algorithm: 'aes-256-cbc' } }), /Invalid archive manifest/);
});
